<?php
namespace qqworld_collector\module\settings; use qqworld_collector\lib; class compression extends lib { public function __construct() { add_action( 'wp_ajax_qqworld-collector-compression-get-attachments-list', array($this, 'get_attachments_list') ); add_action( 'wp_ajax_nopriv_qqworld-collector-compression-get-attachments-list', array($this, 'get_attachments_list') ); add_action( 'wp_ajax_qqworld-collector-compression-compress-single-attachment', array($this, 'compress_single_attachment') ); add_action( 'wp_ajax_nopriv_qqworld-collector-compression-compress-single-attachment', array($this, 'compress_single_attachment') ); add_action( 'wp_ajax_qqworld-collector-compression-compress-attachments', array($this, 'compress_attachment') ); add_action( 'wp_ajax_nopriv_qqworld-collector-compression-compress-attachments', array($this, 'compress_attachment') ); add_filter( 'wp_generate_attachment_metadata', array($this, 'wp_generate_attachment_metadata'), 30, 2); } public function init() { if ( filter_var($this->options->qc_compression_enabled, FILTER_VALIDATE_BOOLEAN) ) { add_filter( 'bulk_actions-upload', array($this, 'add_bulk_actions') ); add_filter( 'handle_bulk_actions-upload', array($this, 'handle_bulk_actions'), 10, 3 ); add_action( 'qqworld-collector-admin-notices-upload', array($this, 'admin_notices') ); add_filter( 'manage_media_columns', array($this, 'manage_media_columns') ); add_action( 'manage_media_custom_column', array($this, 'manage_media_custom_column'), 10, 2 ); } } public function get_attachments_list() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; $paged = $_REQUEST['paged']; $args = array( 'post_type' => 'attachment', 'post_mime_type' => 'image/jpeg', 'meta_key' => '_compressed', 'meta_value' => 1, 'meta_compare' => 'NOT EXISTS', 'posts_per_page' => 1000, 'offset' => 1000*$paged ); $attachments = get_posts($args); $success_message = sprintf(_n('%d uncompressed image of attachments found, compressing...', '%d uncompressed images of attachments found, compressing...', count($attachments), $this->text_domain), number_format_i18n(count($attachments))); $failed_message = __('Congratulations, seems like all images attachments had already compressed.', $this->text_domain); if (!empty($attachments)) { $array = array(); foreach ($attachments as $attachment) $array[] = $attachment->ID; $results = array( 'success' => 1, 'msg' => $success_message, 'attachments' => $array ); } else { $results = array( 'success' => 0, 'msg' => $failed_message ); } echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function compress_single_attachment() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; $attachment_id = $_POST['attachment_id']; $attachment = get_post($attachment_id); $type = $attachment->post_mime_type; $fullsize_path = get_attached_file( $attachment_id ); $file_paths = $this->get_all_thumb_file_full_path($attachment_id, $fullsize_path); $file_paths['full'] = $fullsize_path; $size1 = 0; $size2=0; foreach ($file_paths as $size => $path) { $src = wp_get_attachment_image_src( $attachment_id, $size); $filesize = @filesize($path); if ($filesize) $size1 += $filesize; switch ($type) { case 'image/jpeg': $img = @imagecreatefromjpeg($path); if (@imagejpeg($img, $path, $this->options->qc_compression_quality)) { $sizes[$size] = array( 'success' => 1, 'src' => $src[0], 'path' => $path, 'filesize1' => $filesize ); } break; case 'image/webp': $img = @imagecreatefromwebp($path); if (@imagewebp($img, $path, $this->options->qc_compression_quality)) { $sizes[$size] = array( 'success' => 1, 'src' => $src[0], 'path' => $path, 'filesize1' => $filesize ); } break; } } if (!empty($sizes)) foreach ($sizes as $size => $result) { $filesize = @filesize($result['path']); if ($filesize) { $size2 += $filesize; $sizes[$size]['filesize2'] = $filesize; } } update_post_meta($attachment_id, '_compressed', 1); $msg = sprintf(_n('%d image has been compressed, ', '%d images have been compressed, ', count($sizes), $this->text_domain), number_format_i18n(count($sizes))); $msg .= sprintf(__('Total space saving %s.', $this->text_domain), $this->formatBytes($size1-$size2)); $results = array( 'msg' => $msg, 'sizes' => $sizes ); echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function compress_attachment() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; $sizes = array(); $attachment_id = $_POST['attachment_id']; $fullsize_path = get_attached_file( $attachment_id ); $file_paths = $this->get_all_thumb_file_full_path($attachment_id, $fullsize_path); $file_paths['full'] = $fullsize_path; $size1 = 0; $size2=0; foreach ($file_paths as $size => $path) { remove_filter( 'upload_dir', array($this, 'upload_dir') ); $src = wp_get_attachment_image_src( $attachment_id, $size); add_filter( 'upload_dir', array($this, 'upload_dir') ); $filesize = @filesize($path); $size1 += $filesize; $img = @imagecreatefromjpeg($path); if (@imagejpeg($img, $path, $this->options->qc_compression_quality)) { $sizes[$size] = array( 'success' => 1, 'src' => $src[0], 'path' => $path, 'filesize1' => $filesize ); } } foreach ($sizes as $size => $result) { $filesize = @filesize($result['path']); $size2 += $filesize; $sizes[$size]['filesize2'] = $filesize; } update_post_meta($attachment_id, '_compressed', 1); do_action( 'qqworld-collector-cloud-storage-sync-single-attachment', $attachment_id ); $msg = sprintf(_n('%d image has been compressed, ', '%d images have been compressed, ', count($sizes), $this->text_domain), number_format_i18n(count($sizes))); $msg .= sprintf(__('Total space saving %s.', $this->text_domain), $this->formatBytes($size1-$size2)); $results = array( 'msg' => $msg, 'sizes' => $sizes ); echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function compression_image($path, $mime_type) { if (!in_array($mime_type, array('image/jpeg', 'image/webp'))) return; if (class_exists('Imagick')) { $imagick = new \Imagick(); $imagick->readImage($path); if ($mime_type == 'image/jpeg') $imagick->setCompression(\imagick::COMPRESSION_JPEG); $imagick->setImageCompressionQuality(100-$this->options->qc_compression_quality); $tempPath = ABSPATH . 'temp_output.tmp'; $imagick->writeImage($tempPath); $imagick->clear(); $imagick->destroy(); if (copy($tempPath, $path)) { unlink($tempPath); } } else { switch ($mime_type) { case 'image/jpeg': $img = @imagecreatefromjpeg($path); @imagejpeg($img, $path, $this->options->qc_compression_quality); imagedestroy($img); break; case 'image/webp': if (function_exists('imagecreatefromwebp')) { $img = @imagecreatefromwebp($path); @imagewebp($img, $path, $this->options->qc_compression_quality); imagedestroy($img); } break; } } } public function compression_single_attachment($attachment_id, $metadata = null) { $metadata = $metadata ? $metadata : wp_get_attachment_metadata($attachment_id); $mime_type = get_post_mime_type($attachment_id); $fullsize_path = get_attached_file( $attachment_id ); $file_paths = $this->get_all_thumb_file_full_path($attachment_id, $fullsize_path); $file_paths['full'] = $fullsize_path; foreach ($file_paths as $size => $path) { $this->compression_image($path, $mime_type); } update_post_meta($attachment_id, '_compressed', 1); } public function wp_generate_attachment_metadata($metadata, $attachment_id) { if ($this->options->qc_compression_enabled) { $compressed = get_post_meta($attachment_id, '_added_watermark', true) || get_post_meta($attachment_id, '_compressed', true); if (!$compressed) { $this->compression_single_attachment($attachment_id, $metadata); } } return $metadata; } public function add_bulk_actions($actions) { $actions['compression'] = __('Compression', $this->text_domain); return $actions; } public function handle_bulk_actions( $redirect_to, $doaction, $post_ids ) { switch ($doaction) { case 'compression': foreach ( $post_ids as $attachment_id ) { $this->compression_single_attachment($attachment_id); do_action( 'qqworld-collector-cloud-storage-sync-single-attachment', $attachment_id ); } $redirect_to = add_query_arg( 'bulk_compression', count( $post_ids ), $redirect_to ); break; } return $redirect_to; } public function admin_notices() { if ( ! empty( $_REQUEST['bulk_compression'] ) ) { $hanler_count = intval( $_REQUEST['bulk_compression'] ); printf( '<div id="message" class="updated fade"><p>' . _n( 'Successfully compressed %d attachment.', 'Successfully compressed %d attachments.', $hanler_count, $this->text_domain) . '</p></div>', $hanler_count ); } } public function manage_media_columns( $cols ) { $this->array_insert($cols, 2, array('filesize' => __('Size'))); return $cols; } public function manage_media_custom_column( $column_name, $id ) { switch ($column_name) { case 'filesize': $file_path = get_attached_file($id); $file_size = filesize($file_path); print size_format($file_size); break; } } } ?>